server {
    listen 8080;
    # upstream also has: listen [::]:8080 ipv6only=on;
    # dropped, because a container without IPv6 in its netns makes nginx exit at start
    server_name _;
    access_log off;

    # upstream sets no limit, so nginx's 1 MB default applies, while
    # api/config.sample.js allows a 200 MB upload. Raised to match.
    client_max_body_size 200m;

    location = /i {
        if ($http_content_type = "text/ping") { return 404; }
        proxy_pass http://countly-api:3001;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Real-IP $remote_addr;
    }

    location ^~ /i/ {
        if ($http_content_type = "text/ping") { return 404; }
        proxy_pass http://countly-api:3001;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Real-IP $remote_addr;
    }

    location = /o {
        if ($http_content_type = "text/ping") { return 404; }
        proxy_pass http://countly-api:3001;
    }

    location ^~ /o/ {
        if ($http_content_type = "text/ping") { return 404; }
        proxy_pass http://countly-api:3001;
    }

    location / {
        if ($http_content_type = "text/ping") { return 404; }
        proxy_pass http://countly-frontend:6001;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_read_timeout 120s;
    }
}

